    "codigo": "// userImporter.js

function parseRow(row) {
  return {
    nome:  (row.nome  || '').trim(),
    email: (row.email || '').trim(),
    idade: row.idade,
    plano: (row.plano || '').trim(),
  };
}

function validateFields(parsed) {
  const missingFields = [];
  if (!parsed.nome)  missingFields.push('nome');
  if (!parsed.email) missingFields.push('email');
  return missingFields;
}

function normalizeFields(parsed) {
  const idade = parseInt(parsed.idade, 10);
  return {
    nome:  parsed.nome,
    email: parsed.email.toLowerCase(),
    idade: isNaN(idade) ? 0 : idade,
    plano: parsed.plano.toUpperCase() || 'FREE',
  };
}

function importUsers(rawRows) {
  const valid  = [];
  const errors = [];

  for (let i = 0; i < rawRows.length; i++) {
    const lineNumber = i + 1;
    const parsed      = parseRow(rawRows[i]);
    const missing     = validateFields(parsed);

    if (missing.length > 0) {
      errors.push({ line: lineNumber, missingFields: missing });
      continue;
    }

    valid.push(normalizeFields(parsed));
  }

  return { valid, errors };
}

module.exports = { importUsers };
